// FI-1 — the Workspace <-> canonical documents mapping, proved on all 27 golden fixtures.
// The documents come from Call360-specs …/canonical-documents: generated by the BACKEND from the golden fixtures with
// its own translation and its own SHA-256 (Call360-backend scripts/export_survey_fixture_documents.py, kept current by a
// backend test). This file holds no expected value of its own: it only converts and compares.
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { canonical } from './canonical';
import { addDemoSurvey, addReadinessDemo } from './demo';
import { MappingError, assetKey, changes, fromDocuments, isEmpty, sameDocuments, seqFor, stable, toDocuments, type AssetDoc, type DocumentSet } from './documents';
import { createBlankModule, insertQuestion, newQuestionVersion, updateQuestion } from './ops';
import { sampleWorkspace } from './sample';
import { simulate } from './sim';
import type { Workspace } from './types';

const DIR = resolve(__dirname, '../../../../../Call360-specs/docs/plans/survey-studio/canonical-documents');
const META = { name: 'Fixture', purpose: '', versionLabel: 'Draft' };
/* eslint-disable @typescript-eslint/no-explicit-any */

const files = existsSync(DIR) ? readdirSync(DIR).filter((f) => f.endsWith('.documents.json')).sort() : [];
const load = (f: string): { name: string; set: DocumentSet; raw: any } => {
  const raw = JSON.parse(readFileSync(resolve(DIR, f), 'utf8'));
  return { name: raw.source_fixture, raw, set: { content: raw.content, assets: raw.assets.map((a: any): AssetDoc => ({ kind: a.kind, code: a.code, version: a.version, document: a.document })) } };
};
const byKey = (s: DocumentSet) => new Map(s.assets.map((a) => [assetKey(a), stable(a.document)]));

describe.skipIf(!existsSync(DIR))('the mapping is lossless on all 27 golden fixtures', () => {
  const all = files.map(load);

  it('reads the 27 fixtures of schemas /1 to /5 as exported by the backend', () => {
    expect(all).toHaveLength(27);
    const per = (n: string) => all.filter((f) => f.raw.source_schema.endsWith(`/${n}`)).length;
    expect([per('1'), per('2'), per('3'), per('4'), per('5')]).toEqual([8, 6, 4, 1, 8]);
    for (const f of all) for (const a of f.raw.assets) expect(a.sha256, `${f.name} ${a.code}`).toMatch(/^[0-9a-f]{64}$/); // the server's hashes travel with the documents
  });

  for (const f of all) {
    it(`${f.name} · documents → Workspace → documents is exact`, () => {
      const ws = fromDocuments(f.set, { meta: META });
      const back = toDocuments(ws, ws.surveys[0]!);
      // every document, by identity, is exactly the document the server hashed — so its server hash is still its hash
      expect(stable(back.content)).toBe(stable(f.set.content));
      expect([...byKey(back).keys()].sort()).toEqual([...byKey(f.set).keys()].sort());
      for (const [k, text] of byKey(f.set)) expect(byKey(back).get(k), k).toBe(text);
      expect(sameDocuments(f.set, back)).toBe(true);
      expect(isEmpty(changes(f.set, back))).toBe(true); // opening and saving without an edit sends nothing
    });

    it(`${f.name} · Workspace → documents → Workspace is exact`, () => {
      const ws = fromDocuments(f.set, { meta: META });
      const again = fromDocuments(toDocuments(ws, ws.surveys[0]!), { meta: META });
      expect(canonical(again)).toBe(canonical(ws));
    });

    it(`${f.name} · identities are preserved`, () => {
      const ws = fromDocuments(f.set, { meta: META });
      const sv = ws.surveys[0]!;
      expect(sv.id).toBe((f.set.content as any).code);
      expect(sv.sequence.map((i) => i.id)).toEqual((f.set.content as any).sequence.map((i: any) => i.instance));
      for (const a of f.set.assets.filter((x) => x.kind === 'MODULE')) {
        const m = ws.modules.find((x) => x.code === a.code && x.revision === a.version)!;
        expect(m.nodes.map((n) => n.id)).toEqual((a.document as any).nodes.map((n: any) => n.node));
        expect(m.edges.map((e) => e.id)).toEqual((a.document as any).edges.map((e: any) => e.edge));
      }
      // the execution identity <instance>/<node> of every placed item is unchanged
      const keys = (s: DocumentSet) => (s.content as any).sequence.flatMap((i: any) => {
        const m = s.assets.find((a) => a.kind === 'MODULE' && a.code === i.module.code && a.version === i.module.revision);
        return m ? (m.document as any).nodes.filter((n: any) => n.type !== 'DECISION').map((n: any) => `${i.instance}/${n.node}`) : [];
      });
      expect(keys(toDocuments(ws, sv))).toEqual(keys(f.set));
    });
  }

  it('a survey behaves identically before and after the round trip (the same simulated journey)', () => {
    for (const f of all) {
      const ws = fromDocuments(f.set, { meta: META });
      const again = fromDocuments(toDocuments(ws, ws.surveys[0]!), { meta: META });
      const run = (w: Workspace) => simulate(w, w.surveys[0]!, {}, () => undefined);
      expect(JSON.stringify(run(again)), f.name).toBe(JSON.stringify(run(ws)));
    }
  });
});

describe('the mapping on models made in the editor', () => {
  const sample = (): Workspace => { const [a, id] = addDemoSurvey(sampleWorkspace()); const [b] = [addReadinessDemo(a)].map((r) => (Array.isArray(r) ? r[0] : r)); return { ...(b as Workspace), surveys: (b as Workspace).surveys.filter((s) => s.id === id || true) }; };

  it('every survey of the sample library converts, and converting again changes nothing', () => {
    const ws = sample();
    expect(ws.surveys.length).toBeGreaterThan(0);
    for (const sv of ws.surveys) {
      const docs = toDocuments(ws, sv);
      const back = fromDocuments(docs, { meta: { name: sv.name, purpose: sv.purpose, versionLabel: sv.versionLabel } });
      const docs2 = toDocuments(back, back.surveys[0]!);
      expect(sameDocuments(docs, docs2), sv.id).toBe(true);
      expect(canonical(fromDocuments(docs2, { meta: { name: sv.name, purpose: sv.purpose, versionLabel: sv.versionLabel } }))).toBe(canonical(back));
    }
  });

  it('keeps what an author typed that has no field of its own: module intent, parameter labels, kind', () => {
    let ws = fromDocuments({ content: { schema: 'call360.survey.content/1', code: 'S-T', sequence: [] }, assets: [] }, { meta: META, seq: 500 });
    const [w1, made] = createBlankModule(ws, { name: 'Payment check', kind: 'RISK', intent: 'Confirms how the premium is paid', place: { surveyId: 'S-T', index: 0 } });
    ws = w1;
    const [w2, node] = insertQuestion(ws, made.moduleKey, { entry: true }, { type: 'YES_NO' });
    ws = updateQuestion(w2, made.moduleKey, node, { intent: 'Customer pays by GIRO', text: 'Do you pay by GIRO?' } as any);
    const docs = toDocuments(ws, ws.surveys[0]!);
    const mod = docs.assets.find((a) => a.kind === 'MODULE')!.document as any;
    expect(mod.kind).toBe('RISK');
    expect(mod.authoring).toEqual({ intent: 'Confirms how the premium is paid' });
    const back = fromDocuments(docs, { meta: META, seq: ws.seq });
    expect(canonical(back)).toBe(canonical(ws));
  });

  it('changes() names exactly what an edit touched, and a new question version is a new document, never a changed one', () => {
    const f = load(files.find((x) => x.startsWith('K7'))!);
    const frozen = new Set(f.set.assets.map(assetKey));
    const ws = fromDocuments(f.set, { meta: META, frozen });
    const base = toDocuments(ws, ws.surveys[0]!);
    expect(ws.questions.every((q) => q.published) && ws.modules.every((m) => m.published)).toBe(true);
    // a published module refuses a direct edit (a change is a new version) …
    const m = ws.modules[0]!;
    expect(() => updateQuestion(ws, `${m.code}@${m.revision}`, m.nodes[0]!.id, { intent: 'x' } as any)).toThrow();
    // … and nothing that is frozen is ever in a Save
    expect(isEmpty(changes(base, toDocuments(ws, ws.surveys[0]!)))).toBe(true);
    void newQuestionVersion;
  });

  it('refuses, rather than loses, what it cannot represent', () => {
    const f = load(files.find((x) => x.startsWith('K7'))!);
    const mod = f.set.assets.find((a) => a.kind === 'MODULE' && (a.document as any).nodes.some((n: any) => n.item))!;
    // a second module that places the same item version with ANOTHER wording version
    const other = { ...mod, code: 'M-OTHER', document: { ...mod.document, code: 'M-OTHER', nodes: (mod.document as any).nodes.map((n: any) => (n.item ? { ...n, item: { ...n.item, wording_version: 99 } } : n)) } };
    const two = { ...f.set, assets: [...f.set.assets, other] };
    expect(() => fromDocuments(two, { meta: META })).toThrow(MappingError);
    const noWording = { ...f.set, assets: f.set.assets.filter((a) => a.kind !== 'WORDING') };
    expect(() => fromDocuments(noWording, { meta: META })).toThrow(MappingError);
  });

  it('numbers new codes in a range of the survey\'s own, above anything already used', () => {
    const empty = { content: {}, assets: [] };
    const a = seqFor('S-ALPHA', empty), b = seqFor('S-BETA', empty);
    expect(a).not.toBe(b);
    expect(seqFor('S-ALPHA', empty)).toBe(a); // deterministic
    const used = { content: {}, assets: [{ kind: 'ITEM' as const, code: `Q-NEW-${a + 4}`, version: 1, document: {} }] };
    expect(seqFor('S-ALPHA', used)).toBe(a + 5);
  });
});
